    ],
    context: { root: testRoot },
  })).throwsAsync(CreateErrorCode.missing_description);

  await cleanup();
});

test.case("should throw invalid_capture when an invalid capture value is passed", async assert => {
  await setupTestDir();

  await assert(create.run({
