    flags: [
      { flag: "--description", value: "test description" },
      { flag: "--local" },
      { flag: "--capture", value: "bad-value" },
    ],
    context: { root: testRoot },
  })).throwsAsync(CreateErrorCode.invalid_capture);

  await cleanup();
});

